import Foundation
import Testing
@testable import VistaCore
@testable import VistaMedia

/// Only generated bytes. No network, AV devices or private fixtures.
@Suite(.serialized) @MainActor struct PlaybackRangeDiagnosticsTests {
 typealias D = PlaybackRangeDiagnostics
 let file = try! MediaFile(components:["generated.mp4"])
 @MainActor final class Source: PlaybackCacheSource {
  var epoch: UInt64? = 1, epochCalls = 0, reads = 0, prefetches = 0
  var hold = false, holdPrefetch = false, reject = false, epochOnReturn: UInt64?
  var gate: CheckedContinuation<Void,Never>?
  var isPlaybackRecovering: Bool {false}
  var recoveryActiveStartedAt: TimeInterval? {nil}
  var recoveryActiveElapsed: TimeInterval {0}
  func playbackCacheEpoch() throws -> UInt64? {epochCalls += 1;return epoch}
  func setPlaybackSceneActive(_ active:Bool) {}
  func cancelPlayback() {}
  func awaitPlaybackCleanup() async throws {}
  func fileSize(for file:MediaFile) async throws -> UInt64 {8192}
  func release() {hold=false;holdPrefetch=false;let saved=gate;gate=nil;saved?.resume()}
  func read(_ file:MediaFile,range:Range<UInt64>) async throws -> Data {
   reads += 1
   if hold {await withCheckedContinuation{gate=$0}}
   if let epochOnReturn {epoch=epochOnReturn}
   return Data(repeating:1,count:range.count)
  }
  func readForPrefetch(_ file:MediaFile,range:Range<UInt64>) async throws -> Data {
   prefetches += 1
   if holdPrefetch {await withCheckedContinuation{gate=$0}}
   return Data(repeating:1,count:range.count)
  }
  func readCompletingCachedSegments(_ file:MediaFile,range:Range<UInt64>,segments:[PlaybackCachedSegment],epoch:UInt64) async throws -> PlaybackCachedReadResult {
   let data=try await read(file,range:range)
   return .init(data:data,usedCachedBytes:reject || self.epoch != epoch ? 0:segments.reduce(0){$0+$1.data.count})
  }
 }
 func wrapper(_ source:Source)->PlaybackPrefetchSource {
  let w=PlaybackPrefetchSource(file:file,source:source,configuration:.init(capacityBytes:16,chunkBytes:8,totalCapacityBytes:4096))
  w.setPrefetchEnabled(true);return w
 }
 func until(_ predicate:()->Bool) async throws {
  for _ in 0..<1000 {if predicate(){return};try await Task.sleep(for:.milliseconds(1))}
  throw TestTimeout()
 }
 struct TestTimeout:Error {}
 func read(_ w:PlaybackPrefetchSource,_ range:Range<UInt64>,_ link:PlaybackReadCorrelation) async throws -> Data {
  try await PlaybackReadDiagnosticContext.$correlation.withValue(link){try await w.read(file,range:range)}
 }
 @Test func fullMapIsBoundaryTimeAndHoleIsNotEnvelopeCoverage() async throws {
  let b=Source(),w=wrapper(b)
  _=try await w.read(file,range:0..<8);_=try await w.read(file,range:16..<24)
  let before=w.rangeDiagnosticSnapshot(),calls=b.epochCalls
  #expect(before.cache.map(\.range).sorted{$0.lower<$1.lower} == [D.Span(0..<8),D.Span(16..<24)])
  #expect(before.cache.allSatisfy{$0.kind==1 && $0.producer==nil})
  for _ in 0..<10 {_=w.rangeDiagnosticSnapshot()};#expect(b.epochCalls==calls)
  _=try await w.read(file,range:8..<16)
  let after=w.rangeDiagnosticSnapshot(),work=try #require(after.recent.last)
  #expect(work.range==D.Span(8..<16) && work.availableCount==0 && work.availableBytes==0)
  #expect(work.selected.isEmpty && work.usedCachedBytes==0 && work.callKind == .read)
  #expect(after.cache.reduce(0){$0+Int($1.range.upper-$1.range.lower)}==24)
  #expect(before.cache.count==2) // immutable earlier geometry, not live arena aliases
  try await w.awaitPlaybackCleanup()
 }
 @Test func partialSelectionAndSourceRejectionStayDistinct() async throws {
  for reject in [false,true] {
   let b=Source(),w=wrapper(b)
   _=try await w.read(file,range:4..<8);_=try await w.read(file,range:12..<16)
   b.reject=reject
   _=try await w.read(file,range:2..<18)
   let work=try #require(w.rangeDiagnosticSnapshot().recent.last)
   #expect(work.selectionObserved)
   #expect(work.available==[D.Span(4..<8),D.Span(12..<16)] && work.availableBytes==8)
   #expect(work.selected==work.available && work.selectedBytes==8 && work.usedCachedBytes==(reject ? 0:8))
   #expect(work.callKind == .cachedSegments && work.callResult == .returned && work.bytes==16)
   #expect(!work.fragmentedFallback && work.omittedIntersections==0)
   try await w.awaitPlaybackCleanup()
  }
 }
 @Test func fragmentedPartialFallbackReportsTruncationNotZeroAvailability() async throws {
  let b=Source(),w=wrapper(b)
  for i in UInt64(0)..<9 {_=try await w.read(file,range:(i*2)..<(i*2+1))}
  let before=w.rangeDiagnosticSnapshot();#expect(before.cache.count==9)
  _=try await w.read(file,range:0..<18)
  let work=try #require(w.rangeDiagnosticSnapshot().recent.last)
  #expect(work.availableCount==9 && work.available.count==8 && work.omittedIntersections==1 && work.availableBytes==9)
  #expect(work.fragmentedFallback && work.selected.isEmpty && work.selectedBytes==0 && work.usedCachedBytes==0)
  #expect(work.callKind == .read)
  try await w.awaitPlaybackCleanup()
 }
