 @Test func inFlightJoinCarriesIdentityAcrossExistingPumpTask() async throws {
  let b=Source(),w=wrapper(b)
  _=try await w.fileSize(for:file);_=try await w.read(file,range:0..<8)
  b.holdPrefetch=true;_=try await w.read(file,range:8..<16)
  try await until{b.gate != nil}
  let link=PlaybackReadCorrelation(bridge:70,request:80,chunk:90,seek:3)
  let task=Task{try await read(w,16..<24,link)}
  try await until{w.supplyDiagnosticSnapshot().queueDepth==1}
  let waiting=w.rangeDiagnosticSnapshot(),prefetch=try #require(waiting.current)
  #expect(prefetch.kind == .prefetch && prefetch.range==D.Span(16..<24) && prefetch.correlation==nil)
  #expect(waiting.queued.first?.selectionObserved==false)
  #expect(waiting.queued.first?.correlation==link && waiting.queued.first?.range==D.Span(16..<24))
  b.release();_=try await task.value
  let work=try #require(w.rangeDiagnosticSnapshot().recent.last{$0.kind == .demand})
  #expect(work.correlation==link && work.joinedPrefetch==prefetch.id && work.joinedRange==prefetch.range)
  #expect(work.usedCachedBytes==8 && work.callKind==nil && work.result == .returned)
  try await w.awaitPlaybackCleanup()
 }
 @Test func cancellationSeekAndSourceEpochAreNotJoinedByRange() async throws {
  let b=Source(),w=wrapper(b)
  _=try await w.fileSize(for:file);b.hold=true
  let a=PlaybackReadCorrelation(bridge:1,request:1,chunk:1,seek:1)
  let first=Task{try await read(w,0..<8,a)}
  try await until{b.gate != nil}
  let oldGeneration=w.rangeDiagnosticSnapshot().current?.generation
  w.invalidatePrefetch(reason:.seek)
  let c=PlaybackReadCorrelation(bridge:1,request:2,chunk:2,seek:2)
  let second=Task{try await read(w,0..<8,c)}
  try await until{w.rangeDiagnosticSnapshot().queued.count==1}
  first.cancel();b.epochOnReturn=2;b.release()
  do {_=try await first.value;Issue.record("Cancelled request returned")}catch is CancellationError {}
  _=try await second.value
  let snapshot=w.rangeDiagnosticSnapshot()
  let cancelled=try #require(snapshot.recent.first{$0.correlation==a}),next=try #require(snapshot.recent.first{$0.correlation==c})
  #expect(cancelled.result == .cancelled && cancelled.callResult == .returned && cancelled.generation==oldGeneration)
  #expect(next.generation != oldGeneration && next.selectionEpoch==2 && next.correlation?.seek==2)
  #expect(next.result == .returned && next.usedCachedBytes==0)
  try await w.awaitPlaybackCleanup()
 }
 @Test func historyRemainsRecentAfterEarlierDetailQuotasExhaust() async throws {
  let b=Source(),w=wrapper(b)
  _=try await w.read(file,range:0..<8)
