   _=try await read(w,0..<8,.init(bridge:8,request:i,chunk:i,seek:1))
  }
  let snapshot=w.rangeDiagnosticSnapshot()
  #expect(snapshot.recent.count==64 && snapshot.overwritten==937)
  #expect(snapshot.recent.first?.correlation?.chunk==937 && snapshot.recent.last?.correlation?.chunk==1000)
  #expect(snapshot.observedFrom != nil && snapshot.observedThrough != nil && snapshot.observedThrough!>=snapshot.observedFrom!)
  #expect(snapshot.recent.allSatisfy{$0.usedCachedBytes==8 && $0.callKind==nil})
  try await w.awaitPlaybackCleanup()
 }
 @Test func bridgeReturnIsNotRespondAndDomainsRemainExplicit() throws {
  var d=PlaybackBridgeDiagnostics()
  let a=PlaybackReadCorrelation(bridge:2,request:3,chunk:4,seek:5)
  d.accepted(3,now:1);d.planned(3,range:0..<16);d.began(a,range:0..<8,now:2)
  d.returned(a,bytes:8,now:3)
  #expect(d.snapshot(session:2).active.first?.returnedBytes==8 && d.snapshot(session:2).active.first?.respondedAt==nil)
  d.ended(3,cancelled:true,now:4)
  #expect(d.recent.first?.result==2 && d.recent.first?.deliveredBytes==nil)
  for i in UInt64(1)...1000 {
   let link=PlaybackReadCorrelation(bridge:2,request:i,chunk:i+5,seek:6)
   d.accepted(i,now:Double(i+5));d.began(link,range:0..<8,now:Double(i+5))
   d.returned(link,bytes:8,now:Double(i+5));d.responded(link,bytes:8,now:Double(i+6));d.ended(i,cancelled:false,now:Double(i+6))
  }
  let s=d.snapshot(session:2)
  #expect(s.recent.count==64 && s.overwritten==937 && s.active.isEmpty && s.requests.isEmpty)
  #expect(s.recent.last?.deliveredBytes==8 && s.recent.last?.correlation.seek==6)
 }
 @Test func firstObservedConditionsAreIndependentAndCoverageCannotCrossHoles() throws {
  typealias T=PlaybackWaitEpisodeDiagnostics
  var t=T(),s=T.Snapshot(now:1);s.empty=true;s.coveragePass=true
  _=t.observe(waiting:true,eligible:true,session:1,epoch:1,origin:.loop,snapshot:{s})
  #expect(t.active?.firstEmptyFalseAt==nil && t.active?.firstCoveragePassAt==1)
  t.observeConditions(now:1.1,empty:true,coveragePass:false)
  t.observeConditions(now:1.2,empty:false,coveragePass:false)
  t.observeConditions(now:1.3,empty:false,coveragePass:true)
  let finished=t.abort(.stop,now:2)
  let r=try #require(finished)
  #expect(r.firstEmptyFalseAt==1.2 && r.firstCoveragePassAt==1 && r.emptyObservations==4 && r.coverageObservations==4)
  var atStart=T();s.empty=false;s.coveragePass=nil
  _=atStart.observe(waiting:true,eligible:true,session:2,epoch:1,origin:.loop,snapshot:{s})
  #expect(atStart.active?.firstEmptyFalseAt==1 && atStart.active?.firstCoveragePassAt==nil && atStart.active?.coverageObservations==0)
  #expect(T.coveragePass(position:1,duration:10,speed:2,ranges:[0..<1.2,1.3..<2])==false)
  #expect(T.coveragePass(position:1,duration:10,speed:2,ranges:[0..<1.499])==true)
  #expect(T.coveragePass(position:9.9,duration:10,speed:5,ranges:[9..<10])==true)
  #expect(T.coveragePass(position:.nan,duration:10,speed:2,ranges:[])==nil)
 }
 @Test func nearEOFCoverageUsesGateToleranceEvenWithoutAContainingFrontier() {
  typealias T=PlaybackWaitEpisodeDiagnostics
  let position=9.9999,duration=10.0,speed=5.0,ranges:[Range<Double>]=[9..<9.9998]
  let pass=T.coveragePass(position:position,duration:duration,speed:speed,ranges:ranges)
  var gate=NativeStallRecoveryGate();gate.stalled(eligible:true)
  let actualGatePass=gate.takeResume(now:1,active:true,sceneActive:true,paused:false,seeking:false,ready:true,
   transportPaused:true,bufferEmpty:false,position:position,duration:duration,selectedSpeed:speed,ranges:ranges)
  #expect(pass==true && actualGatePass)
  var boundary=T.Snapshot(now:1)
  boundary.frontier=ranges.filter{$0.lowerBound<=position && $0.upperBound>=position}.map(\.upperBound).max()
  boundary.coveragePass=pass;boundary.empty=false
  var trace=T()
  _=trace.observe(waiting:true,eligible:true,session:1,epoch:1,origin:.loop,snapshot:{boundary})
  #expect(trace.active?.start.frontier==nil && trace.active?.firstCoveragePassAt==1)
  #expect(T.coveragePass(position:position,duration:duration,speed:speed,ranges:[9..<9.998])==false)
 }
 @Test func burstAdmissionPrecedesAllHeavyBoundaryClosuresAndRefills() {
  typealias T=PlaybackWaitEpisodeDiagnostics
  var t=T(),captures=0
  func snapshot(_ now:Double)->T.Snapshot {captures += 1;return T.Snapshot(now:now)}
  for _ in 0..<100 {
   _=t.copiedFrame(now:0,pts:0,clock:0,eligible:true,snapshot:{Issue.record("Unexpected pre-wait capture");return snapshot(0)})
   _=t.observe(waiting:true,eligible:true,session:1,epoch:1,origin:.loop,now:1,snapshot:{snapshot(1)})
   t.resumed(now:1.1,snapshot:{snapshot(1.1)})
   _=t.observe(waiting:false,eligible:true,session:1,epoch:1,origin:.loop,now:1.2,snapshot:{snapshot(1.2)})
   _=t.copiedFrame(now:1.3,pts:1,clock:1,eligible:true,snapshot:{snapshot(1.3)})
   _=t.abort(.stop,now:1.4)
  }
  #expect(captures==16 && t.seen==100 && t.completed==100 && t.suppressed==96)
  _=t.observe(waiting:true,eligible:true,session:1,epoch:1,origin:.loop,now:3,snapshot:{snapshot(3)})
  let emitted=t.abort(.stop,now:3)
  #expect(emitted != nil && captures==17)
 }
 @Test func suppressedWaitRetainsSourceEpochBoundaryWithoutHeavyCapture() {
  typealias T=PlaybackWaitEpisodeDiagnostics
  var t=T()
  for _ in 0..<4 {
   _=t.observe(waiting:true,eligible:true,session:1,epoch:1,origin:.loop,now:1,observedSourceEpoch:1,snapshot:{T.Snapshot(now:1)})
   _=t.abort(.pause,now:1)
  }
  _=t.observe(waiting:true,eligible:true,session:1,epoch:1,origin:.loop,now:1,observedSourceEpoch:1,
   snapshot:{Issue.record("Suppressed start captured heavy evidence");return T.Snapshot(now:1)})
  #expect(!t.capturesActiveDetail && t.active?.start.supply==nil && t.activeSourceEpoch==1)
  // Same cheap comparison as Native observeWait. A token shortage cannot keep
  // one episode alive across two distinct source epochs.
  if let initial=t.activeSourceEpoch,initial != 2 {_=t.abort(.sourceEpoch,now:1.1)}
  #expect(t.active==nil && t.activeSourceEpoch==nil && t.completed==5 && t.suppressed==1)
  _=t.observe(waiting:true,eligible:true,session:1,epoch:1,origin:.loop,now:1.1,observedSourceEpoch:2,
   snapshot:{Issue.record("Suppressed replacement captured heavy evidence");return T.Snapshot(now:1.1)})
  #expect(t.seen==6 && t.activeSourceEpoch==2 && t.active?.episode==6 && !t.capturesActiveDetail)
 }
 @Test(arguments:0..<3) func resumeExitAndFrameOnlyConditionObservationsAreRetained(_ boundary:Int) throws {
  typealias T=PlaybackWaitEpisodeDiagnostics
  var t=T(),start=T.Snapshot(now:1),later=T.Snapshot(now:2)
  start.empty=true;start.coveragePass=false;later.empty=false;later.coveragePass=true
  _=t.copiedFrame(now:0,pts:0,clock:0,eligible:true,snapshot:{start})
  _=t.observe(waiting:true,eligible:true,session:1,epoch:1,origin:.loop,snapshot:{start})
  if boundary==0 {t.resumed(snapshot:{later})}
  if boundary==1 {_=t.observe(waiting:false,eligible:true,session:1,epoch:1,origin:.loop,snapshot:{later})}
  if boundary==2 {
   t.resumed(snapshot:{start})
   _=t.copiedFrame(now:2,pts:2,clock:2,eligible:true,snapshot:{later})
  }
  let done=t.abort(.stop,now:3),record=try #require(done)
  #expect(record.firstEmptyFalseAt==2 && record.firstCoveragePassAt==2)
 }
 @Test func stopPreservesQueuedCancellationAndRetainedSpanUsesMinMax() async throws {
  let b=Source(),w=wrapper(b);b.hold=true
  let a=PlaybackReadCorrelation(bridge:1,request:1,chunk:1,seek:1),c=PlaybackReadCorrelation(bridge:1,request:2,chunk:2,seek:1)
  let first=Task{try await read(w,0..<8,a)}
  try await until{b.gate != nil}
  let second=Task{try await read(w,8..<16,c)}
  try await until{w.rangeDiagnosticSnapshot().queued.count==1}
  w.cancelPlayback()
  do {_=try await second.value;Issue.record("Queued stop returned")}catch is CancellationError {}
  b.release()
  do {_=try await first.value;Issue.record("Active stop returned")}catch is CancellationError {}
  let snapshot=w.rangeDiagnosticSnapshot()
  #expect(snapshot.recent.count==2 && snapshot.recent.allSatisfy{$0.result == .cancelled})
  #expect(snapshot.recent.first?.correlation==c && snapshot.recent.last?.correlation==a)
  #expect(snapshot.recent.first?.selectionObserved==false && snapshot.recent.last?.selectionObserved==true)
  #expect(snapshot.observedFrom==snapshot.recent.last?.queued && snapshot.observedThrough==snapshot.recent.last?.finished)
  var bridge=PlaybackBridgeDiagnostics()
  bridge.accepted(1,now:1);bridge.began(a,range:0..<8,now:1)
  bridge.accepted(2,now:2);bridge.began(c,range:8..<16,now:2)
  bridge.finish(c,result:2,now:3);bridge.finish(a,result:2,now:4)
  #expect(bridge.snapshot(session:1).observedFrom==1 && bridge.snapshot(session:1).observedThrough==4)
  try await w.awaitPlaybackCleanup()
 }
 @Test func worstCaseCompleteRecordFitsIndependentArchiveAndPreservesUInt64() throws {
  let maximum=UInt64.max,range=(maximum-8)..<maximum
  let link=PlaybackReadCorrelation(bridge:maximum,request:maximum,chunk:maximum,seek:Int.max)
  var w=D.Work(kind:.demand,id:maximum,generation:maximum,queued:Double.greatestFiniteMagnitude,range:range,correlation:link)
  var spans:[Range<UInt64>]=[]
  for i in UInt64(0)..<8 {let lower=maximum-32-i*2;spans.append(lower..<(lower+1))}
  w.select(available:spans,selected:spans,epoch:maximum,fragmented:false,validation:true)
  w.availableCount=1024;w.omittedIntersections=1016;w.availableBytes=Int.max
  w.started=Double.greatestFiniteMagnitude;w.finished=Double.greatestFiniteMagnitude;w.completionEpoch=maximum;w.result = .returned;w.bytes=Int.max
  w.publicationRejectedReason=Int.max;w.usedCachedBytes=8;w.joinedPrefetch=maximum;w.joinedRange = .init(range)
  w.callKind = .cachedSegments;w.callStarted=Double.greatestFiniteMagnitude;w.callFinished=Double.greatestFiniteMagnitude;w.callResult = .returned;w.callBytes=Int.max
  var d=D();for _ in 0..<128 {d.append(w)};d.current=w
  let map=(0..<1024).map{_ in D.CacheEntry(range:range,producer:maximum,generation:maximum,epoch:maximum)}
  let forward=D.Forward(cursor:maximum-8,target:maximum,epoch:maximum,generation:maximum,evidence:range,reads:2,suspended:true,enabled:true,paused:true,quarantined:true,reason:7,windowID:maximum,transitionID:maximum,transition:PrefetchForwardTransition.cancelPreserved.rawValue)
  let source=d.snapshot(session:maximum,generation:maximum,epoch:maximum,now:Double.greatestFiniteMagnitude,queued:Array(repeating:w,count:8),cache:map,forward:forward)
  var bridge=PlaybackBridgeDiagnostics()
  for i in UInt64(1)...128 {
   let c=PlaybackReadCorrelation(bridge:maximum,request:maximum-i,chunk:maximum-i,seek:Int.max)
   bridge.accepted(maximum-i,now:Double.greatestFiniteMagnitude);bridge.planned(maximum-i,range:range);bridge.began(c,range:range,now:Double.greatestFiniteMagnitude)
   bridge.returned(c,bytes:Int.max,now:Double.greatestFiniteMagnitude);bridge.responded(c,bytes:Int.max,now:Double.greatestFiniteMagnitude);bridge.ended(maximum-i,cancelled:false,now:Double.greatestFiniteMagnitude)
  }
  for i in UInt64(1)...8 {
   let c=PlaybackReadCorrelation(bridge:maximum,request:maximum-i,chunk:maximum-i,seek:Int.max)
   bridge.accepted(maximum-i,now:Double.greatestFiniteMagnitude);bridge.planned(maximum-i,range:range);bridge.began(c,range:range,now:Double.greatestFiniteMagnitude);bridge.returned(c,bytes:Int.max,now:Double.greatestFiniteMagnitude)
  }
  var s=PlaybackWaitEpisodeDiagnostics.Snapshot(now:Double.greatestFiniteMagnitude);s.ranges=source;s.bridge=bridge.snapshot(session:maximum)
  var oldSupply=PlaybackSupplyDiagnostics()
  oldSupply.beginWork(kind:.demand,id:maximum,generation:maximum,epoch:maximum,now:Double.greatestFiniteMagnitude)
  oldSupply.beginCall(kind:.cachedSegments,now:Double.greatestFiniteMagnitude,observedEpoch:maximum,generation:maximum)
  oldSupply.endCall(result:.returned,bytes:Int.max,now:Double.greatestFiniteMagnitude)
  oldSupply.beginCall(kind:.read,now:Double.greatestFiniteMagnitude,observedEpoch:maximum,generation:maximum)
  s.supply=oldSupply.snapshot(session:maximum,generation:maximum,epoch:maximum,queueDepth:8,oldestQueuedAt:Double.greatestFiniteMagnitude)
  s.clock=Double.greatestFiniteMagnitude;s.rate=5;s.speed=5;s.frontier=Double.greatestFiniteMagnitude;s.lastFrameAt=Double.greatestFiniteMagnitude;s.lastFramePTS=Double.greatestFiniteMagnitude
  s.lastDeliveryAt=Double.greatestFiniteMagnitude;s.deliveryBytes=maximum;s.context=127;s.transport=2;s.empty=false;s.coveragePass=true
  var record=PlaybackWaitEpisodeDiagnostics.Record(session:maximum,episode:maximum,requestEpoch:Int.max,origin:.loop,start:s)
  record.resume=s;record.exit=s;record.frame=s;record.reason = .advanced;record.finished=Double.greatestFiniteMagnitude
  record.notificationAt=Double.greatestFiniteMagnitude;record.resumeCause=Int.max;record.lastResumeAt=Double.greatestFiniteMagnitude
  record.firstCopyAt=Double.greatestFiniteMagnitude;record.firstCopyPTS=Double.greatestFiniteMagnitude;record.firstCopyRelation=3;record.framePTS=Double.greatestFiniteMagnitude
  record.resumeCalls=maximum;record.duplicateCopies=maximum;record.suppressed=maximum
  record.firstEmptyFalseAt=Double.greatestFiniteMagnitude;record.firstCoveragePassAt=Double.greatestFiniteMagnitude;record.lastConditionAt=Double.greatestFiniteMagnitude
  record.emptyObservations=maximum;record.coverageObservations=maximum
  let data=try JSONEncoder().encode(PlaybackLogRecord(waitEpisode:record,build:"92").withWaitLosses(dropped:maximum,rejected:maximum,failures:maximum,missingPayload:maximum,oversize:maximum,encoding:maximum,rotatedFiles:maximum,expiredFiles:maximum))
  print("WAIT_RANGE_MAX_RECORD_BYTES",data.count,"limit",PlaybackLogStore.waitJournalLimit)
  #expect(data.count+1<PlaybackLogStore.waitJournalLimit)
  let decoded=try JSONDecoder().decode(PlaybackLogRecord.self,from:data)
  #expect(decoded.waitEpisode?.start.ranges?.cache.count==1024 && decoded.waitEpisode?.frame?.ranges?.recent.count==64)
  #expect(decoded.waitEpisode?.start.ranges?.recent.first?.range?.upper==UInt64.max)
  #expect(decoded.waitEpisode?.start.ranges?.cacheOmitted==0 && decoded.waitEpisode?.start.ranges?.recent.first?.omittedIntersections==1016)
  #expect(decoded.waitEpisode?.start.bridge?.recent.count==64)
 }
